# Value fixes (existing keys with wrong values — asserted against current value).
FIXES = [
    ("de", "SPACES", "SPACES", "RÄUME"),
    ("es", "Personal", "personal", "Personal"),
]

# (key, lang) pairs where the value legitimately equals the English key.
IDENTICAL_OK = {
    ("Smart Links", "es"), ("Smart Links", "fr"), ("Smart Links", "de"),
    ("Intel Today", "es"), ("Intel Today", "fr"), ("Intel Today", "de"),
    ("Smart Mail", "es"), ("Smart Mail", "fr"), ("Smart Mail", "de"),
    ("Bots", "es"), ("Bots", "fr"), ("Bots", "de"),
    ("In: ", "de"),
    ("TOTAL", "es"), ("TOTAL", "fr"),
    ("LIVE", "de"),
    (" in ", "de"),
    ("Social", "es"), ("Social", "fr"),
    ("Business", "de"),
    ("Contacts", "fr"),
    ("Space", "de"),
    ("Desktop", "de"),
    ("Tablet", "de"),
    ("Direct", "fr"),
    ("Trend", "de"),
    ("message", "fr"), ("messages", "fr"),
    (" messages · ", "fr"),
    (" · Total ", "es"), (" · Total ", "fr"),
    (" Total ", "es"), (" Total ", "fr"),
    ("”", "es"), ("”", "fr"),
    ("Dashboard", "es"), ("Dashboard", "fr"), ("Dashboard", "de"),
    (": “", "es"),
    ("” (", "es"), ("” (", "fr"),
    ("Person", "de"),
    ("”.", "es"), ("”.", "fr"), ("”.", "de"),
}

DE_LEAK = set("äöüßÄÖÜ")

def main():
    with open(P, encoding="utf-8") as f:
        d = json.load(f)
    start = {lang: len(d[lang]) for lang in ("es", "fr", "de")}
    assert start == {"es": 266, "fr": 266, "de": 266}, f"unexpected start counts: {start}"
    seen = set()
    for k, es, fr, de in NEW:
        assert k not in seen, f"duplicate new key: {k!r}"
        seen.add(k)
        for lang in ("es", "fr", "de"):
            assert k not in d[lang], f"COLLISION: {k!r} already in {lang}"
        for lang, v in (("es", es), ("fr", fr), ("de", de)):
            assert isinstance(v, str) and v, f"empty/non-string value for {k!r} in {lang}"
            if lang in ("es", "fr"):
                bad = [c for c in v if c in DE_LEAK]
                assert not bad, f"DE-leak in {lang} value for {k!r}: {bad}"
            if "NayaNET" in k:
                assert "NayaNET" in v, f"NayaNET lost in {lang} value for {k!r}"
            if "Naya" in k:
                assert "Naya" in v, f"Naya lost in {lang} value for {k!r}"
            if v == k and (k, lang) not in IDENTICAL_OK:
                raise AssertionError(f"identical value not allowlisted: {k!r} in {lang}")
        d["es"][k] = es
        d["fr"][k] = fr
        d["de"][k] = de
    for lang, k, old, new in FIXES:
        assert d[lang].get(k) == old, f"FIX precondition failed: {lang}[{k!r}]={d[lang].get(k)!r}, expected {old!r}"
        d[lang][k] = new
    end = {lang: len(d[lang]) for lang in ("es", "fr", "de")}
    assert end == {"es": 266 + len(NEW), "fr": 266 + len(NEW), "de": 266 + len(NEW)}, f"unexpected end counts: {end}"
    # Write via stdout, not open("w"): the EPERM flake truncates-then-fails on
    # direct writes to this path. Caller redirects stdout to a fresh file
    # and renames it over dict-final.json; summary goes to stderr.
    sys.stdout.write(json.dumps(d, ensure_ascii=False, indent=1, sort_keys=True) + "\n")
    sys.stdout.flush()
    print(f"OK: {len(NEW)} new keys; {start} -> {end}; 2 value fixes applied", file=sys.stderr)

if __name__ == "__main__":
    main()
